from __future__ import annotations

from copy import deepcopy

import numpy as np

from monai.utils import MetaKeys

__all__ = ["MetaTensor"]


class MetaTensor:
    def __init__(self, data, affine=None, meta=None):
        self.data = np.asarray(data)
        self.affine = np.asarray(affine if affine is not None else np.eye(self.data.ndim + 1), dtype=float)
        self.meta = dict(meta or {})
        self.meta.setdefault(MetaKeys.AFFINE, self.affine.copy())

    def clone(self):
        return MetaTensor(self.data.copy(), affine=self.affine.copy(), meta=deepcopy(self.meta))

    @property
    def shape(self):
        return self.data.shape

    @property
    def ndim(self):
        return self.data.ndim

